From 48bdaadc2aaccbb6bbaaf003a2fc99a08ff6d4cf Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:26:46 +0100
Subject: [PATCH] globalshortcuts: add next and previous activity shortcuts

The shortcuts to cycle through activities lived in plasmashell, so they
showed up under Plasma Workspace while the ones for each activity were
under Activity Manager. Register them here, next to the others, instead.

BUG: 484583
---
 .../globalshortcuts/GlobalShortcutsPlugin.cpp   | 17 +++++++++++++++++
 1 file changed, 17 insertions(+)

diff --git a/src/service/plugins/globalshortcuts/GlobalShortcutsPlugin.cpp b/src/service/plugins/globalshortcuts/GlobalShortcutsPlugin.cpp
index b08ad2c5..02acb7c4 100644
--- a/src/service/plugins/globalshortcuts/GlobalShortcutsPlugin.cpp
+++ b/src/service/plugins/globalshortcuts/GlobalShortcutsPlugin.cpp
@@ -49,6 +49,20 @@ bool GlobalShortcutsPlugin::init(QHash<QString, QObject *> &modules)
     connect(m_activitiesService, SIGNAL(ActivityAdded(QString)), this, SLOT(activityAdded(QString)));
     connect(m_activitiesService, SIGNAL(ActivityRemoved(QString)), this, SLOT(activityRemoved(QString)));

+    const auto previousActivityAction = m_actionCollection->addAction(QStringLiteral("switch to previous activity"));
+    previousActivityAction->setText(i18nc("@action", "Switch to Previous Activity"));
+    KGlobalAccel::setGlobalShortcut(previousActivityAction, QList<QKeySequence>{});
+    connect(previousActivityAction, &QAction::triggered, this, [this]() {
+        QMetaObject::invokeMethod(m_activitiesService, "PreviousActivity", Qt::QueuedConnection);
+    });
+
+    const auto nextActivityAction = m_actionCollection->addAction(QStringLiteral("switch to next activity"));
+    nextActivityAction->setText(i18nc("@action", "Switch to Next Activity"));
+    KGlobalAccel::setGlobalShortcut(nextActivityAction, QList<QKeySequence>{});
+    connect(nextActivityAction, &QAction::triggered, this, [this]() {
+        QMetaObject::invokeMethod(m_activitiesService, "NextActivity", Qt::QueuedConnection);
+    });
+
     m_actionCollection->readSettings();

     return true;
@@ -87,6 +101,9 @@ void GlobalShortcutsPlugin::activityRemoved(const QString &deletedActivity)

     // Removing all shortcuts that refer to an unknown activity
     for (const auto &action : m_actionCollection->actions()) {
+        if (!action->objectName().startsWith(objectNamePattern.left(objectNamePatternLength))) {
+            continue;
+        }
         const auto actionActivity = activityForAction(action);
         if ((deletedActivity.isEmpty() && !m_activitiesList.contains(actionActivity)) //
             || deletedActivity == actionActivity) {
