 5 files changed, 59 insertions(+), 29 deletions(-)
 create mode 100644 shell/kconf_update/plasmashell-6.9-move-next-previous-activity-shortcuts.cpp
 create mode 100644 shell/kconf_update/plasmashell-6.9-move-next-previous-activity-shortcuts.upd

diff --git a/shell/kconf_update/CMakeLists.txt b/shell/kconf_update/CMakeLists.txt
index 9884aebbe1..f2635a65d7 100644
--- a/shell/kconf_update/CMakeLists.txt
+++ b/shell/kconf_update/CMakeLists.txt
@@ -28,3 +28,10 @@ target_link_libraries(plasmashell-6.5-remove-stop-activity-shortcut PRIVATE KF6:

 install(FILES plasmashell-6.5-remove-stop-activity-shortcut.upd DESTINATION ${KDE_INSTALL_KCONFUPDATEDIR})
 install(TARGETS plasmashell-6.5-remove-stop-activity-shortcut DESTINATION ${KDE_INSTALL_LIBDIR}/kconf_update_bin/)
