+
+install(FILES plasmashell-6.9-move-next-previous-activity-shortcuts.upd DESTINATION ${KDE_INSTALL_KCONFUPDATEDIR})
+install(TARGETS plasmashell-6.9-move-next-previous-activity-shortcuts DESTINATION ${KDE_INSTALL_LIBDIR}/kconf_update_bin/)
diff --git a/shell/kconf_update/plasmashell-6.9-move-next-previous-activity-shortcuts.cpp b/shell/kconf_update/plasmashell-6.9-move-next-previous-activity-shortcuts.cpp
new file mode 100644
index 0000000000..dd6eaebe95
--- /dev/null
+++ b/shell/kconf_update/plasmashell-6.9-move-next-previous-activity-shortcuts.cpp
@@ -0,0 +1,45 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include <KGlobalAccel>
+
+#include <QAction>
+#include <QGuiApplication>
+
+/**
+ * The "Switch to Next/Previous Activity" shortcuts moved from plasmashell to
+ * kactivitymanagerd, next to the per-activity shortcuts; carry over custom ones.
+ */
+int main(int argc, char **argv)
+{
+    QGuiApplication app(argc, argv);
+
+    for (const QString &actionName : {QStringLiteral("switch to next activity"), QStringLiteral("switch to previous activity")}) {
+        QList<QKeySequence> shortcut = KGlobalAccel::self()->globalShortcut(QStringLiteral("plasmashell"), actionName);
+        shortcut.removeAll(QKeySequence());
+
+        QAction oldAction;
+        oldAction.setObjectName(actionName);
+        oldAction.setProperty("componentName", QStringLiteral("plasmashell"));
+        oldAction.setProperty("componentDisplayName", QStringLiteral("plasmashell"));
+        KGlobalAccel::self()->setShortcut(&oldAction, {QKeySequence()}, KGlobalAccel::NoAutoloading);
+        KGlobalAccel::self()->removeAllShortcuts(&oldAction);
+
+        if (shortcut.isEmpty()) {
+            continue;
+        }
+
+        QAction newAction;
+        newAction.setObjectName(actionName);
+        newAction.setProperty("componentName", QStringLiteral("ActivityManager"));
+        newAction.setProperty("componentDisplayName", QStringLiteral("Activity Manager"));
+        // Don't mark kactivitymanagerd's action as inactive when this one goes away
+        newAction.setProperty("isConfigurationAction", true);
+        KGlobalAccel::self()->setShortcut(&newAction, shortcut, KGlobalAccel::NoAutoloading);
+    }
+
+    return 0;
+}
